CREATE TABLE tasks (task_id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, category TEXT NOT NULL, task_type TEXT, estimated_duration INTEGER, predicted_duration INTEGER, difficulty INTEGER, importance INTEGER, deadline INTEGER, status TEXT NOT NULL DEFAULT 'PENDING', created_at INTEGER);
CREATE TABLE task_feedback (feedback_id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL, actual_duration INTEGER, actual_difficulty INTEGER, completion_status TEXT, completed_at INTEGER, notes TEXT, FOREIGN KEY(task_id) REFERENCES tasks(task_id));
CREATE TABLE user_profile (profile_id INTEGER PRIMARY KEY AUTOINCREMENT, wake_time TEXT, sleep_time TEXT, breakfast_time TEXT, lunch_time TEXT, dinner_time TEXT, focus_duration INTEGER, break_duration INTEGER, daily_capacity INTEGER, preferred_start_time TEXT);
CREATE TABLE schedule_items (schedule_id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL, scheduled_date TEXT NOT NULL, start_time INTEGER NOT NULL, end_time INTEGER NOT NULL, is_manually_edited INTEGER DEFAULT 0, status TEXT DEFAULT 'PLANNED', FOREIGN KEY(task_id) REFERENCES tasks(task_id));
CREATE TABLE IF NOT EXISTS learning_snapshots (task_id INTEGER PRIMARY KEY, estimate INTEGER NOT NULL, prediction INTEGER NOT NULL, category TEXT, task_type TEXT, difficulty INTEGER, deadline INTEGER, captured_at INTEGER NOT NULL, evaluable INTEGER NOT NULL, completed_at INTEGER, remaining_override INTEGER, scope_changed INTEGER NOT NULL DEFAULT 0, remaining_anchor_feedback_id INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(task_id) REFERENCES tasks(task_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS feedback_submissions (token TEXT PRIMARY KEY, task_id INTEGER NOT NULL, feedback_id INTEGER NOT NULL, FOREIGN KEY(task_id) REFERENCES tasks(task_id) ON DELETE CASCADE, FOREIGN KEY(feedback_id) REFERENCES task_feedback(feedback_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS session_details (feedback_id INTEGER PRIMARY KEY, source TEXT NOT NULL, timing_valid INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, edited_at INTEGER, FOREIGN KEY(feedback_id) REFERENCES task_feedback(feedback_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS session_segments (feedback_id INTEGER NOT NULL, segment_index INTEGER NOT NULL, started_at INTEGER NOT NULL, ended_at INTEGER NOT NULL, PRIMARY KEY(feedback_id,segment_index), FOREIGN KEY(feedback_id) REFERENCES task_feedback(feedback_id) ON DELETE CASCADE);
